<?php
/**
 * OData v4 CSDL metadata document — CANONICAL url.
 *
 * ROUTING: this is the one file in this task whose name a shell has to quote
 * carefully — nginx maps /api/<path> to /api/<path>.php by literal file
 * placement (see the top-level ROUTING note), so the OData-spec-mandated
 * `<service root>/$metadata` URL can only be served by a file that is
 * literally named "$metadata.php" on disk; there is no other way to make that
 * EXACT url resolve without editing nginx config, which this task forbids.
 * '$' is a perfectly legal filesystem/HTTP-path character (RFC 3986 lists it
 * as a sub-delim, so OData clients send it unencoded); it is only awkward for
 * a human typing shell commands against this file, not for nginx or PHP.
 *
 * GET /api/external/odata/$metadata works because of that file placement.
 * GET /api/external/odata/metadata (metadata.php, no '$') is the easier-to-
 * type alternative documented in this task's report — both return byte-
 * identical output, generated by the SAME ODataDispatch::serveMetadata() call.
 *
 * Power BI's native OData connector requests the canonical '$metadata' URL
 * automatically when given the service root; this file exists specifically so
 * that auto-discovery succeeds without the user needing to know about the
 * '/metadata' alternative at all.
 */

require_once __DIR__ . '/ODataDispatch.php';

ODataDispatch::serveMetadata();
